import React, { useEffect, useState } from 'react';

export default function AdBanner() {
  const [banners, setBanners] = useState([]);
  const [index, setIndex]     = useState(0);
  const [sliding, setSliding] = useState(false);

  useEffect(() => {
    fetch('http://localhost:5000/api/banners/current')
      .then(r => r.json())
      .then(data => { if (data.banners?.length) setBanners(data.banners); })
      .catch(() => {});
  }, []);

  const goTo = (i) => {
    if (i === index) return;
    setSliding(true);
    setTimeout(() => { setIndex(i); setSliding(false); }, 400);
  };

  useEffect(() => {
    if (banners.length <= 1) return;
    const t = setInterval(() => {
      setSliding(true);
      setTimeout(() => {
        setIndex(i => (i + 1) % banners.length);
        setSliding(false);
      }, 400);
    }, 4000);
    return () => clearInterval(t);
  }, [banners]);

  if (!banners.length) return null;

  return (
    <div style={{ position: 'relative', width: '100%', height: 420, overflow: 'hidden', borderRadius: 16, background: '#111' }}>
      {banners.map((b, i) => (
        <img
          key={b.url}
          src={b.url}
          alt=""
          style={{
            position: 'absolute', inset: 0,
            width: '100%', height: '100%',
            objectFit: 'contain',
            opacity: i === index ? (sliding ? 0 : 1) : 0,
            transition: 'opacity 0.4s ease',
            userSelect: 'none',
          }}
        />
      ))}

      {/* dots */}
      {banners.length > 1 && (
        <div style={{ position: 'absolute', bottom: 14, left: '50%', transform: 'translateX(-50%)', display: 'flex', gap: 6, alignItems: 'center' }}>
          {banners.map((_, i) => (
            <div key={i} onClick={() => goTo(i)} style={{
              width: i === index ? 22 : 8, height: 8, borderRadius: 4,
              background: i === index ? '#f97316' : 'rgba(255,255,255,0.5)',
              cursor: 'pointer', transition: 'width 0.3s',
            }} />
          ))}
        </div>
      )}
    </div>
  );
}
